function buildLeadRecord(data={}){const name=String(data.name||'New lead').trim();const source=String(data.source||'Manual').trim();const id=nowId('lead');const context=String(data.context||'').trim();const p={id,name,initials:initialsFor(name),company:String(data.company||'Independent').trim(),role:String(data.role||'Prospect').trim(),email:String(data.email||'').trim(),status:'New lead',intent:'lead',stage:'New lead',value:Number(data.value||0),lastContact:'Just now',summary:context||`New lead captured from ${source}.`,preferences:[],objections:[],promises:[],purchases:[],memory:[`Lead entered Recallya from ${source}.`,...(context?[context]:[])],nextAction:String(data.nextAction||'Send personalized introduction'),nextWhy:`Captured from ${source}. Recallya created the relationship record and is ready to move it into the right follow-up.`,sequence:null,source,sourceDetail:String(data.sourceDetail||''),capturedAt:'Just now',preferredVoice:'sales',salesCue:'Use the source and stated interest to make the first outreach relevant, then ask for one concrete next step.',ownerId:'erica',lifecycle:'Lead',consent:{email:true,sms:false,dm:true,doNotContact:false,preferredChannel:'Email',frequency:'Normal'},internalNotes:[],memoryEvidence:[{id:`${id}-source`,text:`Lead entered Recallya from ${source}.`,source:'Lead intake',sourceDetail:source,confidence:'Explicit',verified:true},...(context?[{id:`${id}-context`,text:context,source:'Inbound message',sourceDetail:'Lead submission',confidence:'Explicit',verified:true}]:[])]};const c={id:nowId('c'),personId:id,time:'Now',needsMe:true,handled:false,waiting:false,preview:context||`New ${source.toLowerCase()} lead ready for follow-up.`,mode:'Approval',voiceId:'sales',messages:context?[{d:'in',text:context,time:'Now'}]:[]};const activity={time:new Date().toISOString(),type:'lead_created',personId:id,text:`Lead captured from ${source}`};return{p,c,activity}}
function createLead(data={}){const {p,c,activity}=buildLeadRecord(data);state.people.unshift(p);state.conversations.unshift(c);state.activities.unshift(activity);save();render();toast(`${p.name} added from ${p.source}`);return p}
function createLeadInWorkspace(workspace,data={}){const d=normalizeWorkspaceData(workspace.data);const {p,c,activity}=buildLeadRecord(data);d.people.unshift(p);d.conversations.unshift(c);d.activities.unshift(activity);workspace.data=d;storage.setItem('recallya-portfolio-v1',JSON.stringify(portfolio));return p}
function parseCsvLine(line){const out=[];let cur='',quoted=false;for(let i=0;i<line.length;i++){const ch=line[i];if(ch==='"'){if(quoted&&line[i+1]==='"'){cur+='"';i++}else quoted=!quoted}else if(ch===','&&!quoted){out.push(cur.trim());cur=''}else cur+=ch}out.push(cur.trim());return out}
function importLeadCsv(text){const lines=text.split(/\r?\n/).filter(x=>x.trim());if(lines.length<2)return 0;const headers=parseCsvLine(lines[0]).map(x=>x.toLowerCase().replace(/[^a-z0-9]+/g,''));let count=0;for(const line of lines.slice(1)){const vals=parseCsvLine(line);const row=Object.fromEntries(headers.map((h,i)=>[h,vals[i]||'']));const name=row.name||row.fullname||[row.firstname,row.lastname].filter(Boolean).join(' ');if(!name)continue;createLead({name,company:row.company||row.organization,email:row.email,role:row.role||row.title,source:'CSV import',value:row.value||row.dealvalue,context:row.context||row.notes||row.message,nextAction:row.nextaction||'Review imported lead and personalize outreach'});count++}return count}
function consumeInboundLeads(){let queue=[];try{queue=JSON.parse(storage.getItem('recallya-inbound-leads')||'[]')}catch{}if(!Array.isArray(queue)||!queue.length)return;storage.removeItem('recallya-inbound-leads');let activeArrivals=0;queue.forEach(x=>{const target=portfolio.workspaces.find(w=>w.id===(x.workspaceId||x.workspace_slug));if(target&&target.id!==activeWorkspaceId)createLeadInWorkspace(target,{...x,source:x.source||'Website form'});else{createLead({...x,source:x.source||'Website form'});activeArrivals++}});persistPortfolio();renderPortfolio();toast(`${queue.length} website lead${queue.length===1?'':'s'} routed to the correct workspace${activeArrivals?` · ${activeArrivals} here`:''}`)}


function ownerFor(p){return state.teamMembers.find(m=>m.id===(p?.ownerId||'erica'))||state.teamMembers[0]}
function timelineFor(p){
  const items=[];
  if(p?.capturedAt)items.push({when:p.capturedAt,title:`Entered Recallya via ${p.source||'CRM'}`,detail:p.sourceDetail||p.summary,kind:'source'});
  const convs=state.conversations.filter(c=>c.personId===p.id);convs.forEach(c=>{(c.messages||[]).forEach(m=>items.push({when:m.time||c.time,title:m.d==='in'?'Customer message':m.d==='ai'?'Recallya replied':'You replied',detail:m.text,kind:'conversation'}))});
  state.promises.filter(x=>x.personId===p.id).forEach(x=>items.push({when:x.due,title:'Commitment',detail:x.text,kind:'promise'}));
  state.documents.filter(x=>x.personId===p.id).forEach(x=>items.push({when:x.added,title:`${x.kind} added`,detail:x.name,kind:'document'}));
  state.quotes.filter(x=>x.personId===p.id).forEach(x=>items.push({when:x.updated,title:`Quote · ${x.status}`,detail:`${x.name} · ${money(x.amount)}`,kind:'quote'}));
  state.meetingNotes.filter(x=>x.personId===p.id).forEach(x=>items.push({when:x.when,title:x.title,detail:x.summary,kind:'meeting'}));
  state.activities.filter(x=>x.personId===p.id).slice(0,8).forEach(x=>items.push({when:(x.time||'').slice(0,10)||'Recent',title:(x.type||'Activity').replaceAll('_',' '),detail:x.text||'',kind:'activity'}));
  return items.slice(-14).reverse();
}
