function renderThreads(){$('#threadList').innerHTML=state.conversations.map(c=>{const p=person(c.personId)||{name:'Unknown',initials:'?'};return `<div class="thread-item ${c.id===activeConversationId?'active':''}" data-conversation="${c.id}"><div class="person-avatar">${esc(p.initials)}</div><div class="thread-copy"><div class="thread-top"><b>${esc(p.name)}</b><time>${esc(c.time)}</time></div><p>${esc(c.preview)}</p><div class="thread-flags">${c.needsMe?'<span class="mini-chip hot">Needs you</span>':''}${c.handled?'<span class="mini-chip">Handled by Recallya</span>':''}${c.waiting?'<span class="mini-chip">Waiting</span>':''}</div></div></div>`}).join('');$$('[data-conversation]').forEach(el=>el.onclick=()=>openConversation(el.dataset.conversation))}
function renderPeople(){const q=$('#peopleSearch')?.value.trim().toLowerCase()||'';const rows=state.people.filter(p=>{if(peopleFilter==='lead'&&p.intent!=='lead')return false;if(peopleFilter==='hot'&&p.intent!=='hot')return false;if(peopleFilter==='stalled'&&!/follow-up|discovery/i.test(`${p.status} ${p.stage}`))return false;if(peopleFilter==='customer'&&p.intent!=='customer')return false;if(q&&!`${p.name} ${p.company} ${p.summary} ${p.stage} ${p.source}`.toLowerCase().includes(q))return false;return true});$('#peopleList').innerHTML=rows.map(p=>`<div class="person-row" data-open-person="${p.id}"><div class="person-avatar">${esc(p.initials)}</div><div class="person-main"><b>${esc(p.name)}</b><span>${esc(p.company)} · ${esc(p.role)}</span><small class="source-line">${esc(p.source)} · ${esc(p.capturedAt)}</small></div><div class="person-context">${esc(p.summary)}</div><div class="person-deal"><b>${esc(p.stage)}</b><span>${p.value?money(p.value):p.intent==='customer'?'Active client':'Value not set'}</span></div><span class="intent-dot ${p.intent==='hot'?'hot':p.intent==='lead'?'lead':''}" title="${esc(p.status)}"></span></div>`).join('');bindPersonOpen()}
function renderLeadSources(){const sources=[['⌂','Website form','Auto-create from demo/contact forms','Ready'],['✉','Email','Recognize new prospect threads','Connect Gmail'],['◷','Calendar / booking','Create records from booked meetings','Connect Calendar'],['⇧','CSV import','Bulk import existing lists','Available'],['↗','API / webhook','Push leads from ads, forms or other CRMs','Ready'],['+','Manual','Fast add from mobile','Available']];$('#leadSourceGrid').innerHTML=sources.map(x=>`<div class="lead-source-card"><span>${x[0]}</span><div><b>${x[1]}</b><small>${x[2]}</small></div><em class="${/Ready|Available/.test(x[3])?'ready':''}">${x[3]}</em></div>`).join('');const counts={};state.people.forEach(p=>counts[p.source]=(counts[p.source]||0)+1);$('#leadSourceSummary').innerHTML=Object.entries(counts).sort((a,b)=>b[1]-a[1]).slice(0,3).map(([name,n])=>`<span><b>${n}</b> ${esc(name)}</span>`).join('')}

function voiceBadge(v){return `<span class="voice-dot" style="--voice-strength:${v.sales}%"></span>`}
function renderVoices(){const list=$('#voiceProfileList');list.innerHTML=state.voiceProfiles.map(v=>`<div class="voice-profile ${v.id==='rouge'?'rouge-voice':''}"><div class="voice-profile-top"><div>${voiceBadge(v)}<div><b>${esc(v.name)}</b><span>${esc(v.use)}</span></div></div><button class="soft-btn small" data-edit-voice="${v.id}">${v.locked?'Configure':'Edit'}</button></div><p>${esc(v.description)}</p><div class="voice-meter-row"><span>Direct ${v.directness}</span><span>Warm ${v.warmth}</span><span>Formal ${v.formality}</span><span>Sell ${v.sales}</span></div></div>`).join('');$('#voiceLaunchStatus').textContent=`${state.voiceProfiles.filter(v=>!v.locked).length} voices`;$$('[data-edit-voice]').forEach(b=>b.onclick=()=>openVoiceDialog(b.dataset.editVoice));fillVoiceSelects()}
function fillVoiceSelects(){const options=state.voiceProfiles.map(v=>`<option value="${v.id}">${esc(v.name)}${v.locked?' · add-on':''}</option>`).join('');['#conversationVoice','#seqVoice','#campaignVoice','#rougeVoice'].forEach(sel=>{const el=$(sel);if(!el)return;const old=el.value;el.innerHTML=options;if(old&&state.voiceProfiles.some(v=>v.id===old))el.value=old});if($('#rougeVoice'))$('#rougeVoice').value=state.rouge.voiceId||'rouge'}
function openVoiceDialog(id=null){const v=id?voice(id):null;$('#voiceDialogTitle').textContent=v?'Edit voice':'Create a voice';$('#voiceId').value=v?.id||'';$('#voiceName').value=v?.name||'';$('#voiceUse').value=v?.use||'Founder / direct messages';$('#voiceDirectness').value=v?.directness??80;$('#voiceWarmth').value=v?.warmth??70;$('#voiceFormality').value=v?.formality??45;$('#voiceSales').value=v?.sales??75;$('#voiceDescription').value=v?.description||'';$('#voiceSamples').value=(v?.samples||[]).join('\n');$('#voiceAvoid').value=(v?.avoid||[]).join(', ');$('#voiceCTA').value=v?.cta||'';updateVoiceRangeOutputs();$('#voiceDialog').showModal()}
function updateVoiceRangeOutputs(){[['#voiceDirectness','#directnessOut'],['#voiceWarmth','#warmthOut'],['#voiceFormality','#formalityOut'],['#voiceSales','#salesOut']].forEach(([i,o])=>{$(o).textContent=$(i).value})}

function channelPolicyClass(c){return c.publishMode==='auto'?'allowed':c.publishMode==='approval'?'approval':'blocked'}
function adaptPost(base,channelId,voiceId,goal,url){const c=channel(channelId);const v=voice(voiceId||c?.voiceId);let text=String(base||'').trim();const cta=url?` ${goal==='Drive website traffic'?'Learn more':'See the next step'}: ${url}`:'';if(channelId==='x'){text=`${text}${cta}`;if(text.length>275)text=text.slice(0,272)+'…'}else if(channelId==='bluesky'){text=`${text}${cta}`;if(text.length>295)text=text.slice(0,292)+'…'}else if(channelId==='linkedin'){text=`${text}\n\n${v.cta||'Take the next step.'}${url?` ${url}`:''}`}else if(channelId==='email'){text=`Subject: ${goal}\n\n${text}\n\n${v.cta||'If this is relevant, reply and I’ll show you the next step.'}${url?`\n${url}`:''}`}else if(channelId==='website'){text=`${text}${url?`\n\n${url}`:''}`}else if(channelId==='reddit'){text=`${text}\n\n${url?`More context: ${url}`:''}`.trim()}return text}
function renderPublisher(){const totals=state.campaigns.reduce((a,c)=>{Object.keys(a).forEach(k=>a[k]+=(c.results?.[k]||0));return a},{posts:0,clicks:0,conversations:0,leads:0,customers:0,revenue:0});$('#publisherSummary').innerHTML=`<div><span>Posts</span><b>${totals.posts}</b></div><div><span>Clicks</span><b>${totals.clicks}</b></div><div><span>Conversations</span><b>${totals.conversations}</b></div><div><span>Leads</span><b>${totals.leads}</b></div><div><span>Revenue</span><b>${money(totals.revenue)}</b></div>`;$('#campaignList').innerHTML=state.campaigns.map(c=>`<div class="campaign-card"><div class="campaign-main"><div class="campaign-title-row"><b>${esc(c.name)}</b><span class="campaign-status ${c.status.toLowerCase()}">${esc(c.status)}</span></div><p>${esc(c.message)}</p><div class="campaign-meta"><span>Goal: ${esc(c.goal)}</span><span>Voice: ${esc(voice(c.voiceId).name)}</span><span>${esc(c.when)}</span></div><div class="channel-pills">${c.channels.map(id=>{const ch=channel(id);return `<span class="channel-pill ${channelPolicyClass(ch)}">${esc(ch?.name||id)} · ${ch?.publishMode==='auto'?'auto-ready':'approval'}</span>`}).join('')}</div></div><div class="campaign-results"><b>${c.results?.leads||0}</b><span>leads</span><small>${c.results?.revenue?money(c.results.revenue):'No revenue yet'}</small><button class="soft-btn small" data-preview-campaign="${c.id}">Preview</button></div></div>`).join('');$('#publisherLaunchStatus').textContent=`${state.campaigns.filter(c=>c.status==='Scheduled').length} scheduled`;renderCampaignChannels();$$('[data-preview-campaign]').forEach(b=>b.onclick=()=>previewCampaign(b.dataset.previewCampaign))}
function renderCampaignChannels(){const box=$('#campaignChannelChecks');if(!box)return;box.innerHTML=state.channels.map(c=>`<label class="channel-check"><input type="checkbox" value="${c.id}" ${['x','website'].includes(c.id)?'checked':''}/><span class="integration-logo mini">${esc(c.icon)}</span><span><b>${esc(c.name)}</b><small>${esc(c.policy)}</small></span><em class="${channelPolicyClass(c)}">${c.publishMode==='auto'?'Auto-ready':'Approval'}</em></label>`).join('')}
function previewCampaign(id){const c=state.campaigns.find(x=>x.id===id);if(!c)return;$('#actionDialogTitle').textContent=`Campaign: ${c.name}`;$('#actionDialogBody').innerHTML=`<div class="channel-previews">${c.channels.map(id=>{const ch=channel(id);return `<section class="channel-preview"><div><b>${esc(ch.name)}</b><span class="channel-pill ${channelPolicyClass(ch)}">${ch.publishMode==='auto'?'Auto-ready':'Approval required'}</span></div><p>${esc(adaptPost(c.message,id,c.voiceId,c.goal,c.url)).replace(/\n/g,'<br>')}</p></section>`}).join('')}</div>`;$('#actionDialog').showModal()}

function renderSequences(){$('#sequenceList').innerHTML=state.sequences.map(s=>`<div class="sequence-item"><div><b>${esc(s.name)}</b><span>${esc(s.goal)} · ${esc(s.mode)} · ${esc(voice(s.voiceId||'sales').name)} · ${s.enrolled} enrolled · ${esc(s.replyRate)} reply rate</span></div><span class="sequence-badge">${esc(s.status)}</span></div>`).join('')}
function renderAutomations(){const html=state.automationRules.map(r=>`<label class="automation-rule"><span><b>${esc(r.name)}</b><small>${esc(r.description)}</small></span><select data-rule-mode="${r.id}" ${!r.enabled?'disabled':''}><option ${r.mode==='Autopilot'?'selected':''}>Autopilot</option><option ${r.mode==='Approval'?'selected':''}>Approval</option><option ${r.mode==='Recommend'?'selected':''}>Recommend</option><option ${r.mode==='Human'?'selected':''}>Human</option></select><input type="checkbox" class="toggle" data-rule-toggle="${r.id}" ${r.enabled?'checked':''}/></label>`).join('');$('#automationRules').innerHTML=html;$('#automationCenterRules').innerHTML=html;$$('[data-rule-toggle]').forEach(el=>el.onchange=()=>{const r=state.automationRules.find(x=>x.id===el.dataset.ruleToggle);r.enabled=el.checked;save();renderAutomations();toast(`${r.name} ${r.enabled?'enabled':'disabled'}`)});$$('[data-rule-mode]').forEach(el=>el.onchange=()=>{const r=state.automationRules.find(x=>x.id===el.dataset.ruleMode);r.mode=el.value;save();renderAutomations();toast(`${r.name}: ${r.mode}`)})}
function renderIntegrations(){const items=[['G','Gmail','Email + sequences','Connect'],['C','Google Calendar','Meetings + reminders','Connect'],['✓','Tasks','Built in','Ready'],['X','X','Publisher + inbound','Connect'],['B','Bluesky','Publisher adapter','Ready'],['W','Website','Chat + lead forms','Ready'],['R','Reddit','Approval-first publisher','Ready'],['in','LinkedIn','Approval/API slot','Connect'],['API','Webhooks','Lead + event endpoint','Ready']];$('#integrationGrid').innerHTML=items.map(x=>`<div class="integration-card"><div class="integration-logo">${x[0]}</div><b>${x[1]}</b><span>${x[2]}</span><em class="${x[3]==='Ready'?'ready':''}">${x[3]}</em></div>`).join('')}
function renderRouge(){const configured=Boolean(state.rouge.enabled);$('#rougeCard').classList.toggle('configured',configured);$('#configureRougeBtn').textContent=configured?'Rouge configured':'Configure Rouge';$('#rougeEnabled').value=String(configured);$('#rougeVoice').value=state.rouge.voiceId||'rouge';$('#rougeProvider').value=state.rouge.provider||'';$('#rougeEndpoint').value=state.rouge.endpoint||'';$('#rougeBoundaries').value=state.rouge.boundaries||'';$('#rougeMode').value=state.rouge.mode||'Approval';$('#rougeCustom').value=state.rouge.custom||'Always require human approval'}
function renderAutomationState(){const paused=state.automationsPaused;$('#globalKillSwitch').textContent=paused?'Resume automations':'Pause automations';$('#globalKillSwitch').classList.toggle('paused',paused);$('#automationMiniText').textContent=paused?'Memory active · actions paused':'Approved automations only';$('#autopilotStatus').textContent=paused?'Paused':'Active';$('#autopilotStatus').classList.toggle('live',!paused)}

function draftFor(p,voiceId='sales',withOffer=false){const v=voice(voiceId);let body='';if(p.id==='marissa')body=`Yes. I would make this a two-location pilot and put the training timeline directly into the proposal so you can see exactly what the lift looks like. That gives you something concrete to take to operations instead of asking them to approve a broad rollout.`;else if(p.id==='devon')body=`Absolutely. I’ll send you a realistic implementation timeline that shows what changes for the frontline team and what does not. The goal is to make the disruption clear before we ask you to take another step.`;else if(p.id==='elena')body=`Yes. I can include manager onboarding as part of the proposal. Since manager adoption is one of your priorities, I would rather make that part of the rollout than leave it as an extra you have to solve later.`;else body=`Thanks for the update. I’ve got the context and the next step captured. I’ll keep this moving without making you repeat anything.`;if(withOffer){body+=`\n\n${p.salesCue||'The natural next step is to move this relationship to one concrete commitment.'}`};if(v.formality<35)body=body.replace(/^Absolutely\./,'Yep.');if(v.directness>85&&!/[.!?]$/.test(body))body+='.';return body}
function openConversation(id){const c=state.conversations.find(x=>x.id===id);if(!c)return;activeConversationId=id;activePersonId=c.personId;const p=person(c.personId);$('#conversationEmpty').hidden=true;$('#conversationActive').hidden=false;$('.inbox-shell').classList.add('conversation-open');$('#convName').textContent=p.name;$('#convMeta').textContent=`${p.company} · ${p.stage}`;fillVoiceSelects();$('#conversationVoice').value=c.voiceId||p.preferredVoice||'sales';$('#convMode').value=c.mode||'Approval';$('#messages').innerHTML=c.messages.map(m=>`<div class="message ${m.d==='in'?'incoming':m.d==='ai'?'ai':'outgoing'}"><span>${esc(m.text)}</span><small>${esc(m.by|| (m.d==='in'?p.name:'You'))} · ${esc(m.time)}</small></div>`).join('');$('#contextRail').innerHTML=`<p class="eyebrow">RELATIONSHIP CONTEXT</p><h3>${esc(p.name)}</h3><p>${esc(p.summary)}</p><div class="context-block"><b>Next best action</b><span>${esc(p.nextAction)}</span><small>${esc(p.nextWhy)}</small></div><div class="context-block sales-context"><b>$ Sales cue</b><span>${esc(p.salesCue)}</span></div><div class="context-block"><b>Voice</b><span>${esc(voice(c.voiceId||p.preferredVoice).name)}</span></div>`;renderThreads()}

function bindPersonOpen(){$$('[data-open-person]').forEach(el=>el.onclick=e=>{e.stopPropagation();openPerson(el.dataset.openPerson)})}
function openPerson(id){const p=person(id);if(!p)return;activePersonId=id;const owner=ownerFor(p);const docs=state.documents.filter(x=>x.personId===p.id);const quotes=state.quotes.filter(x=>x.personId===p.id);const cases=state.serviceCases.filter(x=>x.personId===p.id);const meetings=state.meetingNotes.filter(x=>x.personId===p.id);const mem=p.memoryEvidence||[];$('#personDetail').innerHTML=`<div class="person-hero"><div class="person-top"><div class="person-id"><div class="person-avatar">${esc(p.initials)}</div><div><h2>${esc(p.name)}</h2><p>${esc(p.role)} · ${esc(p.company)}</p></div></div><button class="icon-btn close-detail" id="closePerson">×</button></div><div class="detail-tabs"><span>${esc(p.status)}</span><span>${esc(p.stage)}</span><span>${esc(p.lifecycle||'Opportunity')}</span><span>Source: ${esc(p.source)}</span><span>${p.value?money(p.value):p.intent==='customer'?'Customer':'Value not set'}</span></div></div><div class="detail-body">
<section class="detail-card relationship-owner-card"><div class="detail-card-head"><h3>Relationship owner</h3><button class="soft-btn small" id="handoffBtn">Handoff</button></div><div class="owner-line"><span class="workspace-avatar">${esc(owner.avatar)}</span><div><b>${esc(owner.name)}</b><span>${esc(owner.role)} · ${esc(owner.access)}</span></div></div></section>
<section class="detail-card"><div class="detail-card-head"><h3>Relationship memory</h3><span class="trust-chip">Source-backed</span></div><div class="memory-list evidence-list">${mem.map((e,i)=>`<div class="memory-line evidence-memory"><span>✦</span><span><b>${esc(e.text)}</b><small>${esc(e.source)} · ${esc(e.sourceDetail)} · ${esc(e.confidence)}</small></span><button class="text-btn" data-correct-memory="${i}">Correct</button></div>`).join('')}</div></section>
<section class="detail-card"><div class="detail-card-head"><h3>What matters now</h3><button class="why-link" id="detailWhy">Why this?</button></div><div class="memory-list"><div class="memory-line"><span>→</span><span><b>${esc(p.nextAction)}</b><br>${esc(p.nextWhy)}</span></div><div class="memory-line"><span>!</span><span>${esc(p.objections[0]||'No active objection recorded.')}</span></div><div class="memory-line"><span>✓</span><span>${esc(p.promises[0]||'No open promise.')}</span></div></div><div class="button-row wrap" style="margin-top:12px"><button class="primary-btn small" id="detailDoIt">Do it</button><button class="soft-btn small" id="detailDraft">Draft</button></div></section>
<section class="detail-card timeline-card"><div class="detail-card-head"><h3>Relationship timeline</h3><span class="trust-chip">Story, not activity dump</span></div><div class="timeline-list">${renderTimelineHtml(p)}</div></section>
<section class="detail-card"><h3>Consent & communication</h3><div class="consent-grid"><label><input type="checkbox" id="consentEmail" ${p.consent?.email?'checked':''}/> Email allowed</label><label><input type="checkbox" id="consentDm" ${p.consent?.dm?'checked':''}/> DM allowed</label><label><input type="checkbox" id="consentDnc" ${p.consent?.doNotContact?'checked':''}/> Do not contact</label><label>Preferred channel<select id="preferredChannel"><option ${p.consent?.preferredChannel==='Email'?'selected':''}>Email</option><option ${p.consent?.preferredChannel==='DM'?'selected':''}>DM</option><option ${p.consent?.preferredChannel==='Phone'?'selected':''}>Phone</option></select></label></div></section>
<section class="detail-card"><h3>Documents & proposals</h3><div class="asset-list">${[...docs.map(x=>`<div><b>${esc(x.name)}</b><span>${esc(x.kind)} · ${esc(x.status)}</span></div>`),...quotes.map(x=>`<div><b>${esc(x.name)}</b><span>Quote · ${money(x.amount)} · ${esc(x.status)}</span></div>`)].join('')||'<p class="panel-copy">No documents yet.</p>'}</div><div class="button-row wrap"><button class="soft-btn small" id="addDocumentBtn">+ Document</button><button class="soft-btn small" id="createQuoteBtn">+ Quote / proposal</button></div></section>
<section class="detail-card"><div class="detail-card-head"><h3>Internal team notes</h3><span class="trust-chip">Not customer-visible</span></div><div class="internal-notes">${(p.internalNotes||[]).map(n=>`<div><b>${esc(n.author||'Team')}</b><span>${esc(n.text)}</span></div>`).join('')||'<p class="detail-answer">No internal notes yet.</p>'}</div><form id="internalNoteForm" class="inline-note-form"><input id="internalNoteInput" placeholder="Add a handoff note or @mention..."/><button class="soft-btn small">Add</button></form></section>
<section class="detail-card"><h3>Calls & meeting intelligence</h3>${meetings.length?meetings.map(x=>`<div class="meeting-intel"><b>${esc(x.title)} · ${esc(x.when)}</b><p>${esc(x.summary)}</p><small>Decisions: ${esc((x.decisions||[]).join(' · '))}</small></div>`).join(''):'<p class="detail-answer">No meeting summary captured yet.</p>'}</section>
<section class="detail-card"><h3>Customer service context</h3>${cases.length?cases.map(x=>`<div class="service-case"><b>${esc(x.title)}</b><span>${esc(x.status)} · ${esc(x.priority)}</span></div>`).join(''):'<p class="detail-answer">No active service issue. Selling context is clear.</p>'}</section>
<section class="detail-card"><h3>Conversation voice</h3><p class="detail-answer">${esc(voice(p.preferredVoice||'sales').name)} · ${esc(voice(p.preferredVoice||'sales').description)}</p></section><section class="detail-card selling-card"><h3>$ Always be selling — intelligently</h3><p class="detail-answer">${esc(p.salesCue)}</p></section><section class="detail-card"><h3>Sequence</h3><p class="detail-answer">${p.sequence?`Enrolled in <b>${esc(p.sequence)}</b>. Sequence stops if they reply, book or convert.`:'Not currently enrolled.'}</p><button class="soft-btn small" id="enrollPerson">${p.sequence?'Change sequence':'Add to sequence'}</button></section><section class="detail-card detail-ask"><h3>Ask Recallya about ${esc(p.name.split(' ')[0])}</h3><form id="personAskForm"><input id="personAskInput" placeholder='Ask “What should I do next?”' /><button class="primary-btn small">Ask</button></form><div id="personAnswer" class="detail-answer"></div></section></div>`;$('#personDialog').showModal();$('#closePerson').onclick=()=>$('#personDialog').close();$('#detailDoIt').onclick=()=>showAction(p,'do');$('#detailDraft').onclick=()=>showAction(p,'draft');$('#detailWhy').onclick=()=>showWhy(p);$('#enrollPerson').onclick=()=>{$('#personDialog').close();navigate('more');toast('Choose a sequence from More')};$$('[data-correct-memory]').forEach(b=>b.onclick=()=>correctMemory(p,Number(b.dataset.correctMemory)));$('#handoffBtn').onclick=()=>{const choices=state.teamMembers.map((m,i)=>`${i+1}. ${m.name}`).join('\n');const pick=Number(prompt(`Assign ${p.name} to:\n${choices}`));const m=state.teamMembers[pick-1];if(!m)return;p.ownerId=m.id;state.activities.unshift({time:new Date().toISOString(),type:'handoff',personId:p.id,text:`Assigned to ${m.name}`});save();openPerson(p.id);toast(`Assigned to ${m.name}`)};['consentEmail','consentDm','consentDnc'].forEach(k=>$('#'+k).onchange=()=>{p.consent=p.consent||{};p.consent[k==='consentEmail'?'email':k==='consentDm'?'dm':'doNotContact']=$('#'+k).checked;save();toast('Communication preferences saved')});$('#preferredChannel').onchange=()=>{p.consent=p.consent||{};p.consent.preferredChannel=$('#preferredChannel').value;save()};$('#addDocumentBtn').onclick=()=>{const name=prompt('Document name');if(!name)return;state.documents.push({id:nowId('doc'),personId:p.id,name,kind:'Document',status:'Added',added:'Now'});save();openPerson(p.id)};$('#createQuoteBtn').onclick=()=>{const name=prompt('Proposal / quote name',p.nextAction)||'Proposal';const amount=Number(prompt('Amount',String(p.value||0))||0);state.quotes.push({id:nowId('q'),personId:p.id,name,amount,status:'Draft',updated:'Now'});save();openPerson(p.id);toast('Draft quote created')};$('#internalNoteForm').onsubmit=e=>{e.preventDefault();const text=$('#internalNoteInput').value.trim();if(!text)return;p.internalNotes=p.internalNotes||[];p.internalNotes.unshift({id:nowId('note'),author:'Erica',text,created:'Now'});state.activities.unshift({time:new Date().toISOString(),type:'internal_note',personId:p.id,text});save();openPerson(p.id);toast('Internal note added')};$('#personAskForm').onsubmit=async e=>{e.preventDefault();const q=$('#personAskInput').value.trim();if(!q)return;$('#personAnswer').textContent='Thinking from this relationship history…';$('#personAnswer').innerHTML=esc(await askRecallya(q,p)).replace(/\n/g,'<br>')}}
function showAction(p,mode='do'){const draft=draftFor(p,p.preferredVoice||'sales',true);$('#actionDialogTitle').textContent=mode==='draft'?'Draft in context':'Ready to carry this out';$('#actionDialogBody').innerHTML=`<div class="action-preview"><b>${esc(p.nextAction)}</b><p>${esc(p.nextWhy)}</p></div><div class="action-checks"><div class="action-check"><span>✦</span><span><b>Voice</b><br>${esc(voice(p.preferredVoice||'sales').name)}</span></div><div class="action-check"><span>$</span><span><b>Sales context</b><br>${esc(p.salesCue)}</span></div><div class="action-check"><span>✓</span><span><b>Memory</b><br>Save the outcome and next commitment back to this relationship.</span></div></div><label class="draft-box">Prepared message<textarea id="preparedActionText">${esc(draft)}</textarea></label><div class="button-row" style="margin-top:12px"><button class="soft-btn" id="actionCancelBtn">Cancel</button><button class="primary-btn" id="actionConfirmBtn">${mode==='draft'?'Save draft':'Approve & do it'}</button></div>`;$('#actionDialog').showModal();$('#actionCancelBtn').onclick=()=>$('#actionDialog').close();$('#actionConfirmBtn').onclick=()=>{const c=state.conversations.find(x=>x.personId===p.id);if(c){const txt=$('#preparedActionText').value;c.messages.push({d:mode==='draft'?'out':'ai',text:txt,time:'Now',by:mode==='draft'?'Draft':'Recallya'});c.preview=txt;c.needsMe=mode==='draft';c.handled=mode!=='draft';c.waiting=mode!=='draft'}state.activities.unshift({time:new Date().toISOString(),type:mode==='draft'?'draft_saved':'action_sent',personId:p.id,text:p.nextAction});save();render();$('#actionDialog').close();toast(mode==='draft'?'Draft saved in the conversation':'Approved action carried out') }}

async function askRecallya(question,p=null){try{const r=await fetch('/api/ask',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({question,person:p,workspace:{id:activeWorkspace().id,name:activeWorkspace().name,category:activeWorkspace().category,goal:activeWorkspace().goal,products:activeWorkspace().products},state:{people:state.people,promises:state.promises,agenda:state.agenda,campaigns:state.campaigns,voices:state.voiceProfiles}})});if(r.ok){const data=await r.json();if(data.answer)return data.answer}}catch{}return localAnswer(question,p)}
function localAnswer(q,p=null){const s=q.toLowerCase();if(p){if(/sell|offer|upsell|convert/.test(s))return `${p.salesCue}\n\nThe rule here is to sell the next logical commitment, not force an unrelated offer.`;if(/voice|sound|say/.test(s))return `${voice(p.preferredVoice||'sales').name} is the default voice for this relationship. ${voice(p.preferredVoice||'sales').description}`;if(/price|value|deal/.test(s))return `${p.name} is currently a ${money(p.value)} opportunity at the ${p.stage} stage. The active objection is: ${p.objections[0]||'none recorded'}.`;if(/promise|owe|forget/.test(s))return p.promises.length?`You currently owe ${p.name}: ${p.promises.join('; ')}.`:`I don't have an open promise recorded for ${p.name}.`;if(/what.*next|do next|next step|should i do/.test(s))return `${p.nextAction}. ${p.nextWhy}`;if(/summar|know|history/.test(s))return `${p.summary}\n\nImportant memory: ${p.memory.join(' ')}`;if(/draft|reply|email/.test(s))return draftFor(p,p.preferredVoice||'sales',false);return `${p.summary}\n\nNext best action: ${p.nextAction}. ${p.nextWhy}`}
  if(/campaign|post|publisher|social/.test(s))return `You have ${state.campaigns.length} publisher campaigns. ${state.campaigns.filter(c=>c.status==='Scheduled').length} are scheduled. Recallya adapts each campaign by channel and keeps approval-only channels from auto-publishing.`;
  if(/voice|sound like/.test(s))return `You have ${state.voiceProfiles.length} voice profiles. Core can switch voice by channel, sequence or customer. Rouge has a separate locked profile that passes style and boundaries to its configured external provider.`;
  if(/sell|opportun|convert/.test(s)){const p=state.people.find(x=>x.intent==='hot');return p?`${p.name} at ${p.company} has the clearest immediate selling cue: ${p.salesCue}`:'No high-intent selling cue is active right now.'}
  if(/new lead|lead source|where.*lead/.test(s)){const leads=state.people.filter(x=>x.intent==='lead');return leads.length?`${leads.length} new lead${leads.length===1?'':'s'} are waiting for first action: ${leads.slice(0,4).map(x=>`${x.name} from ${x.source}`).join(', ')}.`:'There are no unworked new leads right now.'}
  if(/follow.?up|needs.*today|attention/.test(s))return state.people.filter(p=>['hot','warm'].includes(p.intent)).slice(0,3).map(p=>`${p.name}: ${p.nextAction}`).join('\n');
  if(/promise|overdue|owe/.test(s))return state.promises.map(x=>x.text).join('\n')||'No open promises.';
  if(/deal|pipeline|likely|move/.test(s))return state.people.filter(p=>p.value).sort((a,b)=>b.value-a.value).slice(0,3).map(p=>`${p.company}: ${money(p.value)} · ${p.stage} · ${p.nextAction}`).join('\n');
  return `Recallya is watching three things at once: relationship context, the next useful action and the next natural conversion opportunity. The system should remove remembering and CRM maintenance from the human without taking away their judgment.`}
function addAskMessage(container,type,text){const div=document.createElement('div');div.className=`ask-message ${type}`;div.innerHTML=type==='bot'?`<b>Recallya</b>${esc(text).replace(/\n/g,'<br>')}`:esc(text);container.appendChild(div);container.scrollTop=container.scrollHeight}

function parseCapture(text){const lower=text.toLowerCase();const p=state.people.find(p=>lower.includes(p.name.split(' ')[0].toLowerCase())||lower.includes(p.company.toLowerCase().split(' ')[0]));const actions=[];if(/send|email|proposal|pricing|timeline|information/.test(lower))actions.push({type:'task',title:shortAction(text,'Send follow-up'),when:/tomorrow/.test(lower)?'Tomorrow':/friday/.test(lower)?'Friday':'Next'});if(/remind|follow up|check back/.test(lower))actions.push({type:'task',title:'Follow up if no response',when:/friday/.test(lower)?'Friday':/monday/.test(lower)?'Monday':/next month/.test(lower)?'Next month':'Later'});if(/meet|call|calendar|appointment|tuesday|wednesday|thursday/.test(lower)&&/\b(at|am|pm|meeting|call)\b/.test(lower))actions.push({type:'meeting',title:`${p?.name||'Customer'} follow-up`,when:extractWhen(text)});return {person:p,actions,memory:text}}
function shortAction(text,fallback){const clean=text.replace(/^(tell recallya[:,]?|recallya[:,]?)/i,'').trim();return clean.length>82?clean.slice(0,79)+'…':clean||fallback}
function extractWhen(text){const day=(text.match(/\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday|tomorrow)\b/i)||[])[0];const time=(text.match(/\b\d{1,2}(?::\d{2})?\s*(?:am|pm)\b/i)||[])[0];return [day,time].filter(Boolean).join(' · ')||'Scheduled'}


function updateWorkspaceChrome(){const w=activeWorkspace();if(!w)return;$('#workspaceName').textContent=w.name;$('#workspaceAvatar').textContent=w.short||initialsFor(w.name);$('#mobileWorkspaceName').textContent=w.name;$('#workspaceLaunchStatus').textContent=`${portfolio.workspaces.length} workspace${portfolio.workspaces.length===1?'':'s'}`;$('#businessProfileName').textContent=w.name;$('#businessCategory').textContent=w.category||'Not set';$('#businessGoal').textContent=w.goal||'Not set';$('#businessWebsite').textContent=w.website||'Not connected';$('#businessProductCount').textContent=`${w.products.length} configured`;$('#businessProductList').innerHTML=w.products.length?w.products.map(p=>`<span class="product-chip"><b>${esc(p.name)}</b>${p.price?`<small>${esc(p.price)}</small>`:''}</span>`).join(''):'<span class="empty-product">No products configured yet.</span>'}
function renderPortfolio(){const metrics=portfolio.workspaces.map(w=>({w,m:workspaceMetrics(w)}));const totals=metrics.reduce((a,x)=>{for(const k of Object.keys(a))a[k]+=x.m[k]||0;return a},{pipeline:0,needs:0,leads:0,tasks:0,promises:0,campaigns:0});$('#portfolioMetrics').innerHTML=`<div><span>Businesses</span><b>${portfolio.workspaces.length}</b><small>isolated workspaces</small></div><div><span>Needs you</span><b>${totals.needs}</b><small>conversations</small></div><div><span>Open pipeline</span><b>${money(totals.pipeline)}</b><small>across businesses</small></div><div><span>Tasks / meetings</span><b>${totals.tasks}</b><small>currently tracked</small></div>`;$('#workspaceCards').innerHTML=metrics.map(({w,m})=>`<article class="workspace-card ${w.id===activeWorkspaceId?'active':''}"><div class="workspace-card-head"><span class="workspace-avatar large">${esc(w.short||initialsFor(w.name))}</span><div><b>${esc(w.name)}</b><small>${esc(w.category||w.type)}</small></div>${w.data?.rouge?.enabled?'<em class="rouge-mini">Rouge</em>':''}</div><div class="workspace-card-stats"><span><b>${m.needs}</b> need you</span><span><b>${m.leads}</b> new leads</span><span><b>${money(m.pipeline)}</b> pipeline</span></div><p>${esc(w.goal||'No primary goal set.')}</p><div class="button-row"><button class="${w.id===activeWorkspaceId?'soft-btn':'primary-btn'} small" data-switch-workspace="${esc(w.id)}">${w.id===activeWorkspaceId?'Current workspace':'Open business'}</button><button class="soft-btn small" data-edit-workspace="${esc(w.id)}">Settings</button></div></article>`).join('');renderWorkspaceDialog()}
function renderWorkspaceDialog(){const list=$('#workspaceDialogList');if(!list)return;list.innerHTML=portfolio.workspaces.map(w=>{const m=workspaceMetrics(w);return`<button class="workspace-dialog-row ${w.id===activeWorkspaceId?'active':''}" data-switch-workspace="${esc(w.id)}"><span class="workspace-avatar">${esc(w.short||initialsFor(w.name))}</span><span><b>${esc(w.name)}</b><small>${m.needs} need you · ${money(m.pipeline)} pipeline</small></span><em>${w.id===activeWorkspaceId?'Current':'Switch'}</em></button>`}).join('')}
function openWorkspaceSwitcher(){renderWorkspaceDialog();$('#workspaceDialog').showModal()}
function openWorkspaceSettings(id=activeWorkspaceId){const w=portfolio.workspaces.find(x=>x.id===id);if(!w)return;$('#workspaceSettingsId').value=w.id;$('#workspaceSettingsTitle').textContent=w.name;$('#workspaceBusinessName').value=w.name;$('#workspaceCategory').value=w.category||'';$('#workspaceWebsite').value=w.website||'';$('#workspaceGoal').value=w.goal||'';$('#workspaceProducts').value=productsText(w.products);$('#workspaceType').value=w.type||'business';$('#workspaceTemplate').value='keep';$('#workspaceSettingsDialog').showModal()}
function portfolioAnswer(q){const s=q.toLowerCase();const rows=portfolio.workspaces.map(w=>({w,m:workspaceMetrics(w)}));if(/attention|needs me|need me|today/.test(s))return rows.map(x=>`${x.w.name}: ${x.m.needs} conversations need you, ${x.m.promises} promises tracked and ${x.m.tasks} tasks/meetings.`).join('\n');if(/pipeline|most/.test(s)){const x=[...rows].sort((a,b)=>b.m.pipeline-a.m.pipeline)[0];return x?`${x.w.name} currently has the largest open pipeline at ${money(x.m.pipeline)}.`:'No pipeline is recorded.'}if(/promise|owe|due/.test(s))return rows.map(x=>`${x.w.name}: ${x.m.promises} open promise${x.m.promises===1?'':'s'}.`).join('\n');if(/lead/.test(s))return rows.map(x=>`${x.w.name}: ${x.m.leads} new lead${x.m.leads===1?'':'s'}.`).join('\n');return rows.map(x=>`${x.w.name}: ${x.m.needs} need you · ${money(x.m.pipeline)} pipeline · ${x.m.leads} new leads.`).join('\n')}

function openAutomationCenter(){$('#automationDialog').showModal()}
function openRouge(){renderRouge();$('#rougeDialog').showModal()}
function setupCampaignDialog(){fillVoiceSelects();renderCampaignChannels();$('#campaignForm').reset();$('#campaignVoice').value='social';$('#campaignDialog').showModal()}
function fillRougeForm(){renderRouge()}

function bindEvents(){
  $$('[data-view]').forEach(b=>b.onclick=()=>navigate(b.dataset.view));$$('[data-nav]').forEach(b=>b.onclick=()=>navigate(b.dataset.nav));
  $('#workspaceSwitcherBtn').onclick=openWorkspaceSwitcher;$('#mobileWorkspaceBtn').onclick=openWorkspaceSwitcher;$('#addWorkspaceBtn').onclick=()=>$('#newWorkspaceDialog').showModal();$('#workspaceDialogAddBtn').onclick=()=>{$('#workspaceDialog').close();$('#newWorkspaceDialog').showModal()};$('#managePortfolioBtn').onclick=openWorkspaceSwitcher;$('#openWorkspaceSettingsBtn').onclick=()=>openWorkspaceSettings();$('#editWorkspaceBtn').onclick=()=>openWorkspaceSettings();
  $('#portfolioAskForm').onsubmit=e=>{e.preventDefault();const q=$('#portfolioAskInput').value.trim();if(!q)return;addAskMessage($('#portfolioAskHistory'),'user',q);$('#portfolioAskInput').value='';addAskMessage($('#portfolioAskHistory'),'bot',portfolioAnswer(q))};$$('#portfolioPrompts button').forEach(b=>b.onclick=()=>{$('#portfolioAskInput').value=b.textContent;$('#portfolioAskForm').requestSubmit()});
  $('#workspaceSettingsForm').onsubmit=e=>{e.preventDefault();const id=$('#workspaceSettingsId').value;const w=portfolio.workspaces.find(x=>x.id===id);if(!w)return;w.name=$('#workspaceBusinessName').value.trim();w.short=initialsFor(w.name);w.category=$('#workspaceCategory').value.trim();w.website=$('#workspaceWebsite').value.trim();w.goal=$('#workspaceGoal').value.trim();w.products=parseProducts($('#workspaceProducts').value);w.type=$('#workspaceType').value;const template=$('#workspaceTemplate').value;if(template!=='keep'){w.data=makeWorkspaceData(w.name,w.type,template);if(id===activeWorkspaceId)replaceState(w.data)}persistPortfolio();render();$('#workspaceSettingsDialog').close();toast(`${w.name} workspace saved`)};
  $('#newWorkspaceForm').onsubmit=e=>{e.preventDefault();const name=$('#newWorkspaceName').value.trim();const id=`ws-${Date.now()}-${Math.random().toString(36).slice(2,6)}`;const type=$('#newWorkspaceType').value;const w={id,name,short:initialsFor(name),type,category:$('#newWorkspaceCategory').value.trim(),website:$('#newWorkspaceWebsite').value.trim(),goal:$('#newWorkspaceGoal').value.trim()||'Convert conversations',products:[],data:makeWorkspaceData(name,type,$('#newWorkspaceTemplate').value)};syncActiveWorkspace();portfolio.workspaces.push(w);persistPortfolio();$('#newWorkspaceDialog').close();e.target.reset();switchWorkspace(id);renderPortfolio();toast(`${name} added as a separate workspace`)};
  document.addEventListener('click',e=>{const sw=e.target.closest('[data-switch-workspace]');if(sw){$('#workspaceDialog')?.close();switchWorkspace(sw.dataset.switchWorkspace)}const edit=e.target.closest('[data-edit-workspace]');if(edit){openWorkspaceSettings(edit.dataset.editWorkspace)}});
  $('#headerAskBtn').onclick=()=>navigate('ask');$('#quickCaptureBtn').onclick=()=>{navigate('today');setTimeout(()=>$('#captureInput').focus(),50)};$('#addActionBtn').onclick=()=>{$('#captureInput').focus();$('#captureInput').scrollIntoView({behavior:'smooth',block:'center'})};
  $('#globalKillSwitch').onclick=()=>{state.automationsPaused=!state.automationsPaused;save();renderAutomationState();toast(state.automationsPaused?'Automations paused. Memory still runs.':'Approved automations resumed.')};
  $('#doItBtn').onclick=()=>showAction(state.people.find(p=>p.intent==='hot')||state.people[0],'do');$('#draftItBtn').onclick=()=>showAction(state.people.find(p=>p.intent==='hot')||state.people[0],'draft');$('#whyItBtn').onclick=()=>showWhy(state.people.find(p=>p.intent==='hot')||state.people[0]);$('#scheduleItBtn').onclick=()=>{const p=state.people.find(p=>p.intent==='hot')||state.people[0];state.agenda.unshift({id:nowId('a'),type:'task',personId:p.id,title:p.nextAction,when:'Tomorrow'});save();renderAgenda();toast('Added to tomorrow’s task list')};
  $('#captureForm').onsubmit=e=>{e.preventDefault();const text=$('#captureInput').value.trim();if(!text)return;const parsed=parseCapture(text);if(parsed.person)parsed.person.memory.unshift(text);parsed.actions.forEach(a=>state.agenda.unshift({id:nowId('a'),type:a.type,personId:parsed.person?.id||state.people[0].id,title:a.title,when:a.when}));state.activities.unshift({time:new Date().toISOString(),type:'capture',personId:parsed.person?.id,text});save();render();$('#captureResult').hidden=false;$('#captureResult').innerHTML=`<b>Captured.</b> ${parsed.person?`Added to ${esc(parsed.person.name)}’s relationship memory. `:'Saved as relationship context. '}${parsed.actions.length?`Created ${parsed.actions.length} action${parsed.actions.length===1?'':'s'}: ${parsed.actions.map(a=>`${esc(a.type)} · ${esc(a.when)}`).join(', ')}.`:'No dated action detected.'}`;$('#captureInput').value=''};
  $('#inboxBack').onclick=()=>$('.inbox-shell').classList.remove('conversation-open');$('#openCustomerBtn').onclick=()=>activePersonId&&openPerson(activePersonId);$('#conversationVoice').onchange=()=>{const c=state.conversations.find(x=>x.id===activeConversationId);if(c){c.voiceId=$('#conversationVoice').value;save();openConversation(c.id);toast(`Voice changed to ${voice(c.voiceId).name}`)}};$('#convMode').onchange=()=>{const c=state.conversations.find(x=>x.id===activeConversationId);if(c){c.mode=$('#convMode').value;save();toast(`Conversation mode: ${c.mode}`)}};$('#suggestReplyBtn').onclick=()=>{const p=person(activePersonId);const c=state.conversations.find(x=>x.id===activeConversationId);if(p)$('#replyText').value=draftFor(p,c?.voiceId||p.preferredVoice,false)};$('#salesReplyBtn').onclick=()=>{const p=person(activePersonId);const c=state.conversations.find(x=>x.id===activeConversationId);if(p)$('#replyText').value=draftFor(p,c?.voiceId||p.preferredVoice,true)};$('#sendReplyBtn').onclick=()=>{const text=$('#replyText').value.trim();if(!text||!activeConversationId)return;const c=state.conversations.find(x=>x.id===activeConversationId);c.messages.push({d:'out',text,time:'Now',by:'You'});c.preview=text;c.needsMe=false;c.waiting=true;$('#replyText').value='';state.activities.unshift({time:new Date().toISOString(),type:'reply_sent',personId:c.personId,text});save();openConversation(c.id);renderMetrics();toast('Reply sent and relationship memory updated')};
  $('#peopleSearch').oninput=renderPeople;$$('[data-people-filter]').forEach(b=>b.onclick=()=>{peopleFilter=b.dataset.peopleFilter;$$('[data-people-filter]').forEach(x=>x.classList.toggle('active',x===b));renderPeople()});
  const openLead=()=>$('#leadDialog').showModal();$('#addLeadBtn').onclick=openLead;$('#addLeadBtnMore').onclick=openLead;$('#importLeadsBtn').onclick=()=>$('#leadCsvInput').click();$('#leadForm').onsubmit=e=>{e.preventDefault();const p=createLead({name:$('#leadName').value,company:$('#leadCompany').value,email:$('#leadEmail').value,role:$('#leadRole').value,source:$('#leadSource').value,value:$('#leadValue').value,context:$('#leadContext').value,nextAction:$('#leadAction').value});$('#leadDialog').close();e.target.reset();openPerson(p.id)};$('#leadCsvInput').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;const count=importLeadCsv(await f.text());e.target.value='';toast(`${count} lead${count===1?'':'s'} imported`)};$('#testLeadFormBtn').onclick=()=>window.open('/lead-capture.html','_blank');$('#copyLeadEndpointBtn').onclick=async()=>{const endpoint=`${location.origin}/api/leads?workspace_slug=${encodeURIComponent(activeWorkspace().id)}`;try{await navigator.clipboard.writeText(endpoint);toast('Lead endpoint copied')}catch{toast(endpoint)}};
  $('#globalAskForm').onsubmit=async e=>{e.preventDefault();const input=$('#globalAskInput');const q=input.value.trim();if(!q)return;addAskMessage($('#globalAskHistory'),'user',q);input.value='';addAskMessage($('#globalAskHistory'),'bot',await askRecallya(q))};$$('#globalPrompts button').forEach(b=>b.onclick=()=>{$('#globalAskInput').value=b.textContent;$('#globalAskForm').requestSubmit()});
  $('#newSequenceBtn').onclick=()=>{fillVoiceSelects();$('#seqVoice').value='sales';$('#sequenceDialog').showModal()};$('#sequenceForm').onsubmit=e=>{e.preventDefault();state.sequences.unshift({id:nowId('s'),name:$('#seqName').value.trim(),goal:$('#seqGoal').value,mode:$('#seqMode').value,voiceId:$('#seqVoice').value,enrolled:0,replyRate:'—',status:'Active'});save();renderSequences();$('#sequenceDialog').close();e.target.reset();toast('Sequence created')};
  $('#openPublisherBtn').onclick=()=>$('#newCampaignBtn').scrollIntoView({behavior:'smooth',block:'center'});$('#newCampaignBtn').onclick=setupCampaignDialog;$('#campaignForm').onsubmit=e=>{e.preventDefault();const channels=$$('#campaignChannelChecks input:checked').map(x=>x.value);if(!channels.length)return toast('Choose at least one channel');const mode=$('#campaignMode').value;const campaign={id:nowId('camp'),name:$('#campaignName').value.trim(),goal:$('#campaignGoal').value,message:$('#campaignMessage').value.trim(),url:$('#campaignUrl').value.trim(),voiceId:$('#campaignVoice').value,mode,when:$('#campaignWhen').value,status:mode==='Draft only'?'Draft':'Scheduled',channels,results:{posts:0,clicks:0,conversations:0,leads:0,customers:0,revenue:0}};state.campaigns.unshift(campaign);state.activities.unshift({time:new Date().toISOString(),type:'campaign_created',text:campaign.name});save();renderPublisher();$('#campaignDialog').close();toast('Campaign built. Channel-specific versions are ready.')};
  $('#openVoiceStudioBtn').onclick=()=>$('#voiceProfileList').scrollIntoView({behavior:'smooth',block:'center'});$('#newVoiceBtn').onclick=()=>openVoiceDialog();['#voiceDirectness','#voiceWarmth','#voiceFormality','#voiceSales'].forEach(id=>$(id).oninput=updateVoiceRangeOutputs);$('#voiceForm').onsubmit=e=>{e.preventDefault();const existingId=$('#voiceId').value;const id=existingId||nowId('voice');const v={id,name:$('#voiceName').value.trim(),use:$('#voiceUse').value,directness:Number($('#voiceDirectness').value),warmth:Number($('#voiceWarmth').value),formality:Number($('#voiceFormality').value),sales:Number($('#voiceSales').value),description:$('#voiceDescription').value.trim(),samples:$('#voiceSamples').value.split(/\n+/).map(x=>x.trim()).filter(Boolean),avoid:$('#voiceAvoid').value.split(',').map(x=>x.trim()).filter(Boolean),cta:$('#voiceCTA').value.trim(),locked:existingId==='rouge'};const idx=state.voiceProfiles.findIndex(x=>x.id===id);if(idx>=0)state.voiceProfiles[idx]=v;else state.voiceProfiles.push(v);save();renderVoices();renderSequences();renderPublisher();$('#voiceDialog').close();toast('Voice profile saved')};
  $('#openAutomationCenterBtn').onclick=openAutomationCenter;
  $('#configureRougeBtn').onclick=openRouge;$('#rougeForm').onsubmit=e=>{e.preventDefault();state.rouge={enabled:$('#rougeEnabled').value==='true',voiceId:$('#rougeVoice').value,provider:$('#rougeProvider').value.trim(),endpoint:$('#rougeEndpoint').value.trim(),boundaries:$('#rougeBoundaries').value.trim(),mode:$('#rougeMode').value,custom:$('#rougeCustom').value};save();renderRouge();$('#rougeDialog').close();toast(state.rouge.enabled?'Rouge configuration saved':'Rouge remains off')};
  $('#teamForm').onsubmit=e=>{e.preventDefault();const name=$('#teamName').value.trim();if(!name)return;state.teamMembers.push({id:nowId('member'),name,role:$('#teamRole').value.trim()||'Team member',access:$('#teamAccess').value,status:'active',avatar:initialsFor(name)});save();renderTeamDialog();renderTrustCenter();e.target.reset();toast('Team member added')};
  $$('[data-close]').forEach(b=>b.onclick=()=>$('#'+b.dataset.close).close());document.addEventListener('click',e=>{['personDialog','actionDialog','leadDialog','sequenceDialog','campaignDialog','voiceDialog','automationDialog','rougeDialog','workspaceDialog','workspaceSettingsDialog','newWorkspaceDialog','whyDialog','teamDialog'].forEach(id=>{const d=$('#'+id);if(e.target===d)d.close()})})
}

function render(){updateWorkspaceChrome();renderPortfolio();renderPriorities();renderPromises();renderAgenda();renderMetrics();renderThreads();renderPeople();renderLeadSources();renderSequences();renderVoices();renderPublisher();renderAutomations();renderIntegrations();renderRouge();renderAutomationState();renderTrustCenter();renderTeamDialog();bindPersonOpen()}

render();bindEvents();consumeInboundLeads();fillRougeForm();